class Student:
    def __init__(self, name, number):
        self.name = name
        self.scores = [0] * number

    def get_name(self):
        return self.name

    def get_score(self, i):
        return self.scores[i - 1]

    def set_score(self, i, score):
        self.scores[i - 1] = score

    def get_average(self):
        return sum(self.scores) / len(self.scores)

    def get_high_score(self):
        return max(self.scores)

    def __str__(self):
        score_text = " ".join(str(s) for s in self.scores)
        return f"Name: {self.name}\nScores: {score_text}"

s = Student("Maria", 5)
print(s)
s.set_score(1, 100)
print()
print(s)
print("high score:", s.get_high_score())
print("average:", s.get_average())
print("first score:", s.get_score(1))
print("name:", s.get_name())

