class Rectangle:
    def __init__(self, l, w):
        self.length = l
        self.width = w

    def area(self):
        return self.length * self.width

    @staticmethod
    def combined_area(r1, r2):
        return r1.area() + r2.area()

rect_1 = Rectangle(12, 27)
rect_2 = Rectangle(9, 3)
combined = Rectangle.combined_area(rect_1, rect_2)
print(combined)

